class Inventory:
    def __init__(self, stock=None):
        self.stock = dict(stock or {})

    def apply_orders(self, orders):
        """Apply a batch of (sku, qty) orders, reducing stock."""
        # Validate all qtys and check stock before modifying
        # Accumulate quantities per SKU across the batch
        sku_qtys = {}
        for sku, qty in orders:
            if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
                raise ValueError("qty must be a positive int")
            sku_qtys[sku] = sku_qtys.get(sku, 0) + qty

        # Check if stock is sufficient for each SKU
        for sku, total_qty in sku_qtys.items():
            if sku not in self.stock or self.stock[sku] < total_qty:
                raise InventoryError(f"Insufficient stock for {sku}")

        # Apply orders atomically
        for sku, total_qty in sku_qtys.items():
            self.stock[sku] -= total_qty

    def restock(self, sku, qty):
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("qty must be a positive int")
        self.stock[sku] = self.stock.get(sku, 0) + qty

    def available(self, sku):
        return self.stock.get(sku, 0)","path":"inventory.py"}
